with open('/tmp/prev_session.jsonl') as f:
    for line in f:
        recs.append(json.loads(line))
def walk(obj):
    if isinstance(obj, dict):
        for v in obj.values(): yield from walk(v)
    elif isinstance(obj, list):
        for v in obj: yield from walk(v)
    elif isinstance(obj, str):
        yield obj
ops = []
for i, rec in enumerate(recs):
    if rec.get('type') != 'message': continue
    m = rec.get('message', {})
    content = m.get('content')
    if not isinstance(content, list): continue
    for block in content:
        if not isinstance(block, dict): continue
        call = block.get('toolCall', block)
        if not isinstance(call, dict): continue
        args = call.get('arguments') or {}
        name = call.get('name') or block.get('name')
        blob = json.dumps(args)
        if 'ci_watchdog_tag_retrigger_guard_test' in blob:
            ops.append((i, rec['timestamp'], name, len(blob)))
for o in ops: print(o)
